<script setup lang="ts">
import { computed, ref } from 'vue'
import BaseModal from './BaseModal.vue'
import type { AdvisorDetail, Guidance } from '../types/domain'
import { formatDateTime, pathLabel, statusLabel } from '../utils/format'
const props=defineProps<{ student:AdvisorDetail; saving:boolean }>()
const emit=defineEmits<{ close:[]; submit:[payload:{content:string;adviceType:Guidance['adviceType'];suggestedTask?:string;retestReason?:string}] }>()
type RecordValue=Record<string,unknown>
const asRecord=(value:unknown):RecordValue=>value&&typeof value==='object'&&!Array.isArray(value)?value as RecordValue:{}
const asList=(value:unknown):RecordValue[]=>Array.isArray(value)?value.map(asRecord):[]
const detail=computed(()=>asRecord(props.student.detail)), profile=computed(()=>asRecord(detail.value.profile)), portrait=computed(()=>asRecord(detail.value.portrait)), goal=computed(()=>asRecord(detail.value.goal)), plan=computed(()=>asRecord(detail.value.plan)), recommendation=computed(()=>asRecord(detail.value.recommendation))
const tasks=computed(()=>asList(detail.value.tasks)), reviews=computed(()=>asList(detail.value.reviews)), recommendations=computed(()=>asList(recommendation.value.results))
const type=ref<Guidance['adviceType']>('COMMENT'), content=ref(''), suggestedTask=ref(''), retestReason=ref('')
const adviceLabel=(value:Guidance['adviceType'])=>({COMMENT:'指导意见',SUGGEST_TASK:'建议任务',SUGGEST_RETEST:'建议重新测评'} as Record<Guidance['adviceType'],string>)[value]
function submit(){emit('submit',{content:content.value.trim(),adviceType:type.value,suggestedTask:suggestedTask.value.trim()||undefined,retestReason:retestReason.value.trim()||undefined});emit('close')}
</script>
<template><BaseModal @close="emit('close')"><section class="modal-card advisor-detail-modal"><header><div><p class="eyebrow">学生详情</p><h2>{{String(profile.name||'学生详情')}}</h2><p>{{String(profile.className||'未填写班级')}} · {{student.id}}</p></div><button class="outline-btn" @click="emit('close')">关闭</button></header><div class="advisor-detail-scroll"><section class="advisor-detail-section"><h3>档案概览</h3><div class="detail-kv"><div><small>档案完整度</small><b>{{profile.completeness??'—'}}<i v-if="profile.completeness!==undefined">%</i></b></div><div><small>发展意向</small><b>{{pathLabel(String(profile.developmentIntention||''))}}</b></div><div><small>专业大类</small><b>{{String(profile.majorCategory||'未填写')}}</b></div><div><small>兴趣偏好</small><b>{{Array.isArray(profile.interestPrefs)?profile.interestPrefs.join('、'):'未填写'}}</b></div></div></section><section v-if="portrait.summary||portrait.completeness!==undefined" class="advisor-detail-section"><h3>能力画像</h3><p>{{String(portrait.summary||'暂无画像摘要')}}</p><div class="detail-tags"><span v-for="item in (Array.isArray(portrait.strengths)?portrait.strengths:[])" :key="String(item)">优势：{{item}}</span><span v-for="item in (Array.isArray(portrait.explore)?portrait.explore:[])" :key="String(item)">待探索：{{item}}</span></div></section><section class="advisor-detail-section detail-split"><div><h3>目标与计划</h3><p><b>主目标：</b>{{String(asRecord(goal.primary).name||'尚未设定')}}</p><p><b>备选目标：</b>{{String(asRecord(goal.backup).name||'尚未设定')}}</p><p><b>计划：</b>{{String(plan.goalSummary||'尚未制定')}}</p><p><b>状态：</b>{{statusLabel(String(plan.status||''))}}</p></div><div><h3>推荐方向</h3><p v-for="item in recommendations.slice(0,3)" :key="String(item.directionId)"><b>第 {{item.rank??'—'}} 名</b> {{String(item.directionId||'方向')}} · {{item.score??'—'}} 分</p><p v-if="!recommendations.length">暂无推荐结果。</p></div></section><section class="advisor-detail-section"><h3>计划任务</h3><div class="detail-timeline"><article v-for="task in tasks" :key="String(task.id)"><div><b>{{String(task.title||'未命名任务')}}</b><small>{{String(task.month||'未排期')}} · {{String(task.type||task.taskType||'学习任务')}} · {{statusLabel(String(task.status||''))}}</small></div><span>{{task.deadline?formatDateTime(String(task.deadline)):'无截止日期'}}</span></article><p v-if="!tasks.length">暂无计划任务。</p></div></section><section class="advisor-detail-section"><h3>阶段复盘</h3><div class="detail-timeline"><article v-for="review in reviews" :key="String(review.id)"><div><b>{{String(review.cycle||'阶段复盘')}}</b><small>{{statusLabel(String(review.status||''))}} · {{review.submittedAt?formatDateTime(String(review.submittedAt)):'未提交'}}</small></div><span>{{review.advisorRequested?'已请求指导':'未请求指导'}}</span></article><p v-if="!reviews.length">暂无阶段复盘。</p></div></section><section class="advisor-detail-section"><h3>历史指导记录</h3><div class="guidance-history"><article v-for="item in student.guidance" :key="item.id"><div><em>{{adviceLabel(item.adviceType)}}</em><time>{{formatDateTime(item.createdAt)}}</time></div><b>{{item.content}}</b><p v-if="item.suggestedTask">建议任务：{{item.suggestedTask}}</p><p v-if="item.retestReason">复测原因：{{item.retestReason}}</p></article><p v-if="!student.guidance.length">暂无历史指导记录。</p></div></section><form class="advisor-guidance-form" @submit.prevent="submit"><p class="eyebrow">填写指导意见</p><h3>发送新的指导</h3><label>类型<select v-model="type"><option value="COMMENT">指导意见</option><option value="SUGGEST_TASK">建议任务</option><option value="SUGGEST_RETEST">建议重新测评</option></select></label><label>指导内容<textarea v-model.trim="content" required maxlength="2000" placeholder="清晰说明观察、建议与下一步行动"></textarea></label><label v-if="type==='SUGGEST_TASK'">建议任务<input v-model.trim="suggestedTask" required maxlength="500"></label><label v-if="type==='SUGGEST_RETEST'">重新测评原因<input v-model.trim="retestReason" required maxlength="500"></label><div><button type="button" class="outline-btn" @click="emit('close')">取消</button><button class="primary-btn" :disabled="saving||!content">{{saving?'正在发送…':'发送指导 →'}}</button></div></form></div></section></BaseModal></template>
